static async Task<long> TotalAsync(int[] a, int workers) {
    var parts = Enumerable.Range(0, workers).Select(i => Task.Run(() => {
        int lo = i * a.Length / workers, hi = (i + 1) * a.Length / workers;
        long s = 0; for (int k = lo; k < hi; k++) s += a[k];
        return s;
    })).ToArray();
    long[] res = await Task.WhenAll(parts);      // dispatch + join
    return res.Sum();                            // combine
}
